const parts = []
// bug7043：convertToPixel 返回画布 buffer 像素，而 clip-path:path() 作用于 CSS 像素；
// 高分屏 devicePixelRatio≈1.871 下二者不等，必须换算，否则多边形错位、热力外溢邻区。
const rect = dom.getBoundingClientRect()
const sx = dom.width ? rect.width / dom.width : 1
const sy = dom.height ? rect.height / dom.height : 1
polygons.forEach((rings) => {
  rings.forEach((ring) => {
    if (!ring || ring.length < 3) return
    const pts = ring
      .map((c) => chart.convertToPixel({ geoIndex: 0 }, [Number(c[0]), Number(c[1])]))
      .filter((p) => p && isFinite(p[0]) && isFinite(p[1]))
      .map((p) => [p[0] * sx, p[1] * sy])
    if (pts.length < 3) return
    parts.push('M' + pts.map((p) => p[0].toFixed(2) + ' ' + p[1].toFixed(2)).join('L') + 'Z')

